<script setup lang="ts">
import { computed,onBeforeUnmount,ref,watch } from 'vue';
import { useRoomStore } from '../../stores/room';
import { usePartyActionsStore } from '../../stores/party-actions';
import type { MusicQuizSnapshot } from '../../contracts/musicquiz';
import RoomAudioClip from '../../components/RoomAudioClip.vue';
import UiButton from '../../components/UiButton.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import StatusSlot from '../../components/StatusSlot.vue';
const room=useRoomStore(),actions=usePartyActionsStore(),state=computed(()=>room.snapshot as MusicQuizSnapshot),draft=ref(''),composing=ref(false),storageNotice=ref(''),localError=ref(''),confirm=ref<InstanceType<typeof ConfirmDialog>|null>(null);
const active=computed(()=>room.connected&&!room.terminal),blocked=computed(()=>!active.value||room.busy||actions.pending),draftIdentity=computed(()=>state.value?`musicquiz:${room.code}:${state.value.me}:${state.value.roundId}`:'');
let savedKey='';
function save(){if(!savedKey)return;try{sessionStorage.setItem(savedKey,JSON.stringify({text:draft.value}));}catch{storageNotice.value='此分頁無法保存草稿，請保持頁面開啟。';}}
function forget(){if(savedKey)try{sessionStorage.removeItem(savedKey);}catch{}savedKey='';}
watch([()=>draftIdentity.value,()=>state.value?.phase,()=>state.value?.submitted],()=>{
  if(!state.value)return;
  if(state.value.phase!=='answering'||state.value.submitted){forget();draft.value='';localError.value='';return;}
  const next=draftIdentity.value;if(next===savedKey)return;forget();savedKey=next;draft.value='';
  try{const cached=JSON.parse(sessionStorage.getItem(next)||'null');if(typeof cached?.text==='string'&&cached.text.length<=80&&!/[\u0000-\u001f\u007f]/.test(cached.text))draft.value=cached.text;}catch{storageNotice.value='無法讀取先前草稿，請重新輸入。';}
},{immediate:true});
watch([()=>room.scope,()=>state.value?.roundId,()=>state.value?.phase,()=>state.value?.submitted],()=>{confirm.value?.cancel();localError.value='';});
function limit(){if(!composing.value){let value='';for(const glyph of draft.value){if(value.length+glyph.length>80)break;value+=glyph;}draft.value=value;save();}}
async function guess(){if(composing.value||blocked.value||state.value.phase!=='answering'||state.value.submitted)return;const value=draft.value.trim();if(!value){localError.value='請輸入歌名，或選擇略過。';return;}localError.value='';save();const key=draftIdentity.value;if(await actions.command('guess',{text:value})&&key===draftIdentity.value)forget();}
async function pass(){if(blocked.value||state.value.phase!=='answering'||state.value.submitted)return;const scope=room.scope,round=state.value.roundId;if(!await confirm.value?.ask('略過後，本題不能再送出歌名。','略過這一題？'))return;if(scope===room.scope&&round===state.value.roundId&&state.value.phase==='answering'&&!state.value.submitted&&!blocked.value)await actions.command('guess',{text:'',pass:true});}
function visibility(){if(document.hidden){save();confirm.value?.cancel();}}
document.addEventListener('visibilitychange',visibility);
onBeforeUnmount(()=>{save();document.removeEventListener('visibilitychange',visibility);});
</script>
<template><section class="vue-game-panel vue-musicquiz-stage" aria-labelledby="musicquizHeading"><header><small>LISTEN · GUESS · REVEAL</small><h1 id="musicquizHeading">{{ state.phase==='waiting'?'聽六秒，你猜得出嗎？':state.phase==='answering'?'先聽旋律，再填入歌名':state.phase==='reveal'?'本題答案已揭曉':state.interrupted?'本場中止':'本場成績' }}</h1><p>自製傳統／古典旋律，不按速度計分。</p></header><div class="vue-musicquiz-audio-slot"><RoomAudioClip v-if="state.audioUrl" :key="state.roundId || 'waiting'" :src="state.audioUrl" title="本題六秒旋律開頭" :active="active" /><p v-else>房主開始後，這裡會出現本題播放器。</p></div><div class="vue-musicquiz-action-slot">
  <template v-if="state.phase==='answering'"><p class="vue-musicquiz-progress">{{ state.readyIds.length }}／{{ state.players.length }} 位已作答</p><form v-if="!state.submitted" @submit.prevent="guess"><label for="musicquizAnswer">歌名（最多 80 字元）</label><input id="musicquizAnswer" v-model="draft" maxlength="80" autocomplete="off" :disabled="blocked" @input="limit" @compositionstart="composing=true" @compositionend="composing=false;limit()" @keydown.enter="(composing || $event.isComposing || $event.keyCode===229) && $event.preventDefault()"><div class="vue-musicquiz-buttons"><UiButton icon="send" type="submit" label="送出猜測" :disabled="blocked||composing||!draft.trim()" /><UiButton icon="next" label="這題略過" :disabled="blocked" @click="pass" /></div></form><div v-else class="vue-musicquiz-submitted"><strong>已作答</strong><p>你的答案：{{ state.myAnswer || '略過' }}</p><p>等待全桌完成後，由房主揭曉。</p></div><UiButton v-if="room.host" icon="check" label="全員作答，揭曉答案" :disabled="blocked||!state.canReveal" @click="actions.command('reveal')" />
  </template><template v-else-if="state.phase==='reveal'"><h2>{{ state.results.at(-1)?.title }}</h2><UiButton v-if="room.host" icon="next" label="下一題" :disabled="blocked" @click="actions.command('next')" /><p v-else>等待房主開始下一題。</p></template><template v-else-if="state.phase==='finished'"><p v-if="state.interrupted">玩家離席，本場中止。只保留已完成的回合與分數。</p><template v-else-if="state.winner"><h2>最高分 {{ state.winner.score }} 分</h2><p>{{ state.winner.names.join('、') }}{{ state.winner.names.length>1?' 並列':'' }}獲勝</p></template><ol class="vue-musicquiz-rankings"><li v-for="player in [...state.players].sort((a,b)=>Number(b.score)-Number(a.score))" :key="player.id"><strong>{{ player.name }}</strong><span>{{ player.score }} 分</span></li></ol></template><template v-else><img class="vue-game-waiting-art" :src="room.host?'/assets/stitch/waiting-host.jpg':'/assets/stitch/waiting-guest.jpg'" alt=""><p>{{ room.host?'一個人也可以開始，或邀請朋友一起猜歌。':'等待房主開始，先和朋友打聲招呼。' }}</p></template>
</div><StatusSlot :message="localError||actions.notice||storageNotice" :error="!!localError||(!actions.pending && !!actions.notice)||!!storageNotice" /><div class="vue-musicquiz-retry-slot"><UiButton v-if="actions.canRetry" icon="refresh" label="重試同一操作" :disabled="blocked" @click="actions.retrySame()" /></div></section><section class="vue-game-panel vue-musicquiz-review" aria-labelledby="musicquizReview"><h2 id="musicquizReview">本場回顧</h2><p v-if="!state.results.length">完成一題後，答案與全桌猜測會顯示在這裡。</p><ol v-else><li v-for="result in state.results" :key="result.round"><h3>第 {{ result.round }} 題 · {{ result.title }}</h3><ul><li v-for="(answer,index) in result.answers" :key="result.round+':'+index"><strong>{{ answer.name }}</strong><span>{{ answer.pass?'略過':answer.text }}</span><span>{{ answer.correct?'✓ +1 分':'未猜中' }}</span></li></ul></li></ol></section><ConfirmDialog ref="confirm" /></template>
